'use strict';
// `this` is decided by HOW a function is called (call time), not where it is written.
function who() {
  return this === undefined ? 'undefined' : this.name;
}
const alice = { name: 'Alice', who };
const bob = { name: 'Bob' };

console.log('obj.fn():        ', alice.who());            // implicit: Alice
console.log('fn.call(bob):    ', who.call(bob));          // explicit: Bob
