// What `new` does, written by hand.
function myNew(Ctor, ...args) {
  const obj = Object.create(Ctor.prototype);   // steps 1 and 2: fresh object + prototype link
  const result = Ctor.apply(obj, args);         // step 3: run with this = obj
  const isObj = result !== null && (typeof result === 'object' || typeof result === 'function');
  return isObj ? result : obj;                  // step 4: returned object wins, primitives ignored
}

