// A bind polyfill that also supports `new`.
function myBind(target, thisArg, ...preset) {
  if (typeof target !== 'function') throw new TypeError('not callable');
  function bound(...later) {
    const args = [...preset, ...later];
    if (new.target) {                                  // called with new: ignore thisArg
      const nt = new.target === bound ? target : new.target;
      return Reflect.construct(target, args, nt);
    }
    return target.apply(thisArg, args);                // normal call
  }
  Object.defineProperty(bound, 'name', { value: 'bound ' + target.name });
  Object.defineProperty(bound, 'length', { value: Math.max(0, target.length - preset.length) });
  return bound;
}

