  constructor(id) { this.id = id; }
  click = () => 'field ' + this.id;
}
const A = [new Proto(1), new Proto(2)];
const B = [new Field(1), new Field(2)];

console.log('proto shared fn:', A[0].click === A[1].click);  // true
console.log('field shared fn:', B[0].click === B[1].click);  // false
console.log('field own prop :', Object.hasOwn(B[0], 'click'), Object.hasOwn(A[0], 'click'));

const detachedField = B[0].click;
console.log('detached field :', detachedField());            // works
const detachedProto = A[0].click;
try { detachedProto(); } catch (e) { console.log('detached proto :', e.constructor.name); }

